// Swap is one residency slot that the heavy verticals take turns in: a
// request makes its vertical resident, evicting whichever other one is,
// and runs with the slot held, so at most one of them is ever staged and
// only one of their requests runs at a time. After Idle with no request
// the slot is emptied, so at rest they hold nothing.
//
// The price is a load on a switch: ~28 s for image, ~16 s for music
// (measured by TestStagingSkipsTheQueue); video stages per request anyway
// and has nothing to load.
type Swap struct {
	idle time.Duration
	sem  chan struct{} // held by a running request, a switch, or the idle unload

	mu    sync.Mutex // cur, gen, timer
	cur   Swappable
	gen   int // bumped by every Hold, so a stale idle timer does nothing
	timer *time.Timer
}

// NewSwap is an empty slot. idle 0 never unloads on idle.
func NewSwap(idle time.Duration) *Swap {
	return &Swap{idle: idle, sem: make(chan struct{}, 1)}
}

// Hold waits for the slot, makes v resident, and returns the release, which
// the caller runs when its request is done. A waiting caller gives up when
// ctx does: an image request queued behind a video is a client that may
// hang up. A failed load leaves the slot empty.
func (s *Swap) Hold(ctx context.Context, v Swappable) (release func(), err error) {
	select {
	case s.sem <- struct{}{}:
	case <-ctx.Done():
		return nil, ctx.Err()
	}
	s.mu.Lock()
	s.gen++
---
//
// **Nothing is resident between requests.** A request stages the text
// encoder (50 GB), frees it, stages the transformer (44 GB), frees it, and
// stages the video VAE (7 GB), so the process holds the host-side pieces
// (tokenizer, audio decoder: 0.3 GB) at rest and ~50 GB at a request's peak
// (VIDEO.md decision 2, M-o5).
//
// **It takes the Swap for a request** and has nothing to load: holding the
// slot is what evicts image or music first, and keeps them out until the
// video is done.
//
// **The device is shared, in two ways** (VIDEO.md M9). The stagings do not
// take it at all: they allocate, build pipelines and write mapped memory,
// and none of that touches the queue, so ~2 minutes of a request's disk
// reads run while speech and images have the device. What does take it --
// the encoder's forward, each transformer forward, the VAE decode -- yields
// it between submissions (each ≤ 800 ms by construction) to whoever is
// waiting, so a speech request queued behind a 35 s forward waits for one
// submission rather than the forward.
type Video struct {
	opt  VideoOptions
	id   string
	pipe *pipeline.Pipeline

	mu  sync.Mutex // rng
	rng *rand.Rand
}

// NewVideo loads the host-side pieces. Nothing is staged on the device.
func NewVideo(opt VideoOptions) (*Video, error) {
	if opt.ID == "" {
		opt.ID = defaultVideoModelID
	}
	if opt.Device == nil {
		return nil, fmt.Errorf("backend: the video pipeline needs a device; there is no host path for it")
	}
	if opt.Swap == nil {
		return nil, fmt.Errorf("backend: the video pipeline needs a swap slot")
	}
	d := opt.Device
	bank := qwen.BankQ8
	if opt.FP16 {
		bank = qwen.BankFP16
	}
	p, err := pipeline.New(d.dev, opt.Model, pipeline.Options{
		MaxPrompt: opt.MaxPrompt,
		Bank:      bank,
		BankCache: opt.BankCache,
		Hold: func(fn func() error) error {
			return d.Do(func(*vk.Device) error { return fn() })
		},
		Between: func() { d.yield() },
	})
	if err != nil {
		return nil, fmt.Errorf("backend: loading %s: %w", opt.Model, err)
	}

